-- TradePro database – schema + starter data (schema version 11)
-- Generated by make_sql.php on 2026-11-11 10:14 UTC. Contains NO users, trades, payments or secrets.
-- Import: mysql -u root -p < database.sql   (or phpMyAdmin > Import). Safe to run on an existing database: it only creates what is missing.
-- First admin: admin@example.com / the DEFAULT_ADMIN_PASSWORD from config.php – change it after the first login.

CREATE DATABASE IF NOT EXISTS `tradepro` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `tradepro`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------------------ admins
CREATE TABLE IF NOT EXISTS `admins` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL DEFAULT 'Admin',
  `email` varchar(150) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `last_login` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_admin_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ users
CREATE TABLE IF NOT EXISTS `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `email` varchar(150) NOT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `password_hash` varchar(255) NOT NULL,
  `active_account` enum('demo','inr','usdt') NOT NULL DEFAULT 'demo',
  `status` enum('active','blocked') NOT NULL DEFAULT 'active',
  `email_verified_at` datetime DEFAULT NULL,
  `pin_hash` varchar(255) DEFAULT NULL,
  `pin_fails` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `pin_locked_until` datetime DEFAULT NULL,
  `app_lock` tinyint(1) NOT NULL DEFAULT 0,
  `theme` varchar(8) DEFAULT NULL,
  `last_login` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wallets
CREATE TABLE IF NOT EXISTS `wallets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `type` enum('demo','inr','usdt') NOT NULL,
  `balance` decimal(18,4) NOT NULL DEFAULT 0.0000,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wallet` (`user_id`,`type`),
  CONSTRAINT `fk_wallet_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ assets
CREATE TABLE IF NOT EXISTS `assets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `symbol` varchar(20) NOT NULL,
  `name` varchar(60) NOT NULL,
  `category` varchar(20) NOT NULL DEFAULT 'forex',
  `decimals` tinyint(3) unsigned NOT NULL DEFAULT 4,
  `payout_percent` decimal(5,2) DEFAULT NULL,
  `provider` varchar(20) DEFAULT NULL,
  `source_symbol` varchar(40) DEFAULT NULL,
  `chart_provider` varchar(20) DEFAULT NULL,
  `chart_symbol` varchar(40) DEFAULT NULL,
  `tv_symbol` varchar(60) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_asset_symbol` (`symbol`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ trades
CREATE TABLE IF NOT EXISTS `trades` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `asset_id` int(10) unsigned NOT NULL,
  `account_type` enum('demo','inr','usdt') NOT NULL,
  `direction` enum('up','down') NOT NULL,
  `amount` decimal(18,4) NOT NULL,
  `payout_percent` decimal(5,2) NOT NULL,
  `open_price` decimal(18,6) NOT NULL,
  `close_price` decimal(18,6) DEFAULT NULL,
  `open_ts` int(10) unsigned NOT NULL,
  `expiry_ts` int(10) unsigned NOT NULL,
  `status` enum('open','won','lost','draw') NOT NULL DEFAULT 'open',
  `profit` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `notified` tinyint(1) NOT NULL DEFAULT 0,
  `settle_note` varchar(120) DEFAULT NULL,
  `settled_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_trade_user` (`user_id`,`status`),
  KEY `idx_trade_due` (`status`,`expiry_ts`),
  KEY `fk_trade_asset` (`asset_id`),
  KEY `idx_trade_open_ts` (`open_ts`),
  CONSTRAINT `fk_trade_asset` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_trade_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ transactions
CREATE TABLE IF NOT EXISTS `transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `account_type` enum('demo','inr','usdt') NOT NULL,
  `type` varchar(30) NOT NULL,
  `amount` decimal(18,4) NOT NULL,
  `balance_after` decimal(18,4) NOT NULL,
  `ref_id` bigint(20) unsigned DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_tx_user` (`user_id`,`created_at`),
  CONSTRAINT `fk_tx_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ payment_requests
CREATE TABLE IF NOT EXISTS `payment_requests` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `type` enum('deposit','withdraw') NOT NULL,
  `account_type` enum('inr','usdt') NOT NULL,
  `amount` decimal(18,4) NOT NULL,
  `fee` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `method` varchar(30) NOT NULL,
  `details` varchar(255) NOT NULL,
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `admin_note` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `processed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pr_status` (`status`,`type`),
  KEY `idx_pr_user` (`user_id`),
  CONSTRAINT `fk_pr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ settings
CREATE TABLE IF NOT EXISTS `settings` (
  `k` varchar(60) NOT NULL,
  `v` text NOT NULL,
  PRIMARY KEY (`k`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ admin_logs
CREATE TABLE IF NOT EXISTS `admin_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` int(10) unsigned NOT NULL,
  `action` varchar(60) NOT NULL,
  `detail` varchar(255) DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ price_ticks
CREATE TABLE IF NOT EXISTS `price_ticks` (
  `asset_id` int(10) unsigned NOT NULL,
  `ts` int(10) unsigned NOT NULL,
  `price` decimal(18,6) NOT NULL,
  `qts` int(10) unsigned NOT NULL,
  PRIMARY KEY (`asset_id`,`ts`),
  KEY `idx_tick_ts` (`ts`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ password_resets
CREATE TABLE IF NOT EXISTS `password_resets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kind` enum('user','admin','verify') NOT NULL,
  `account_id` int(10) unsigned NOT NULL,
  `token_hash` char(64) NOT NULL,
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_token` (`token_hash`),
  KEY `idx_reset_acc` (`kind`,`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ cg_rounds
CREATE TABLE IF NOT EXISTS `cg_rounds` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `secs` int(10) unsigned NOT NULL,
  `start_ts` int(10) unsigned NOT NULL,
  `end_ts` int(10) unsigned NOT NULL,
  `period_no` varchar(24) NOT NULL,
  `result` tinyint(3) unsigned DEFAULT NULL,
  `settled_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_round` (`secs`,`start_ts`),
  KEY `idx_round_end` (`settled_at`,`end_ts`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ cg_bets
CREATE TABLE IF NOT EXISTS `cg_bets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `round_id` int(10) unsigned NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `kind` enum('color','number') NOT NULL,
  `pick` varchar(8) NOT NULL,
  `amount` decimal(18,4) NOT NULL,
  `status` enum('open','won','lost') NOT NULL DEFAULT 'open',
  `payout` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_cgb_round` (`round_id`),
  KEY `idx_cgb_user` (`user_id`,`id`),
  CONSTRAINT `fk_cgb_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ mk_markets
CREATE TABLE IF NOT EXISTS `mk_markets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(60) NOT NULL,
  `open_time` char(5) NOT NULL,
  `close_time` char(5) NOT NULL,
  `days` varchar(20) NOT NULL DEFAULT '1,2,3,4,5,6',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ mk_results
CREATE TABLE IF NOT EXISTS `mk_results` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `market_id` int(10) unsigned NOT NULL,
  `day` date NOT NULL,
  `open_panna` char(3) DEFAULT NULL,
  `open_digit` tinyint(3) unsigned DEFAULT NULL,
  `close_panna` char(3) DEFAULT NULL,
  `close_digit` tinyint(3) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mk_day` (`market_id`,`day`),
  CONSTRAINT `fk_mkr_market` FOREIGN KEY (`market_id`) REFERENCES `mk_markets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ mk_bets
CREATE TABLE IF NOT EXISTS `mk_bets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `market_id` int(10) unsigned NOT NULL,
  `day` date NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `game` enum('single','jodi','panna') NOT NULL,
  `session` enum('open','close') NOT NULL,
  `pick` varchar(3) NOT NULL,
  `amount` decimal(18,4) NOT NULL,
  `status` enum('open','won','lost') NOT NULL DEFAULT 'open',
  `payout` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_mkb_mkt` (`market_id`,`day`,`status`),
  KEY `idx_mkb_user` (`user_id`,`id`),
  CONSTRAINT `fk_mkb_market` FOREIGN KEY (`market_id`) REFERENCES `mk_markets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mkb_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ payout_accounts
CREATE TABLE IF NOT EXISTS `payout_accounts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `kind` enum('upi','bank','trc20','bep20') NOT NULL,
  `label` varchar(60) NOT NULL,
  `data` text NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_payout_user` (`user_id`),
  CONSTRAINT `fk_payout_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ kyc
CREATE TABLE IF NOT EXISTS `kyc` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `full_name` varchar(100) NOT NULL,
  `pan_number` char(10) NOT NULL,
  `aadhaar_last4` char(4) NOT NULL,
  `pan_file` varchar(60) NOT NULL,
  `aadhaar_file` varchar(60) NOT NULL,
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `admin_note` varchar(255) DEFAULT NULL,
  `submitted_at` datetime NOT NULL DEFAULT current_timestamp(),
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_kyc_user` (`user_id`),
  KEY `idx_kyc_status` (`status`),
  CONSTRAINT `fk_kyc_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------ mail_log
CREATE TABLE IF NOT EXISTS `mail_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `to_email` varchar(150) NOT NULL,
  `subject` varchar(200) NOT NULL,
  `ok` tinyint(1) NOT NULL DEFAULT 0,
  `error` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

